   'life.plan.school-evening':{pack:'translate(-236px,12px)',pencil:'translate(-279px,-71px)'},
   'life.plan.pool-return':{hang:'translate(-72px,153px) scaleY(.3)',wash:'translate(-256px,34px)'},
   'life.plan.bedtime':{toys:'translate(81px,37px)',tomorrow:'translateY(35px)',story:'translateY(30px)'},
